"""Mix sound effects, room tone and optional credits music with the narration. Usage: python sound_mix.py <project_dir>
Reads cues.json: {"narration": "cut.m4a", "out": "mix.m4a", "room_tone_seconds": 220,
  "music": {"file": "song.mp3", "start": 63, "length": 30, "gap": 1.0, "level_db": -16},      (optional, appended after the narration)
  "effects": {"crickets": {"prompt": "...", "seconds": 5}},                                   (generated by sfx.py)
  "cues": [{"effect": "crickets", "at": 36.7, "length": 2.8, "level_db": -36, "fade": 0.4}]}
"at" is seconds on the narration track. level_db is the target mean level; narration sits near -18, so -36 is a bed and -24 is a hit.
Nobody has heard this mix until a person plays it: levels are computed, not auditioned."""
import subprocess, re, sys, json, glob
O = sys.argv[1]; C = json.load(open(f"{O}/cues.json"))
def mean(f, pre=()):
    out = subprocess.run(["ffmpeg", "-hide_banner", *pre, "-i", f, "-af", "volumedetect", "-f", "null", "-"], capture_output=True, text=True).stderr
    return float(re.search(r"mean_volume: (-?[\d.]+)", out).group(1))
def dur(f): return float(subprocess.check_output(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", f]))
inputs = ["-i", f"{O}/{C['narration']}"]; fc = []; labels = ["[0:a]"]; total = dur(f"{O}/{C['narration']}")
for i, c in enumerate(C.get("cues", []), 1):
    f = glob.glob(f"{O}/sfx/{c['effect']}.*")[0]; inputs += ["-i", f]; L, fd = c["length"], c.get("fade", 0.05)
    fc.append(f"[{i}:a]atrim=0:{L},afade=t=in:d={fd},afade=t=out:st={L-fd-0.05:.2f}:d={fd+0.05:.2f},volume={c['level_db']-mean(f):.1f}dB,"
              f"aformat=sample_rates=48000:channel_layouts=stereo,adelay={int(c['at']*1000)}:all=1[s{i}]"); labels.append(f"[s{i}]")
m = C.get("music")
if m:
    k = len(inputs) // 2; f = f"{O}/{m['file']}"; inputs += ["-i", f]; at = total + m.get("gap", 1.0); L = m["length"]
    gain = m.get("level_db", -16) - mean(f, ("-ss", str(m["start"]), "-t", str(L)))
    fc.append(f"[{k}:a]atrim={m['start']}:{m['start']+L},asetpts=PTS-STARTPTS,afade=t=in:d=0.5,afade=t=out:st={L-3}:d=3,volume={gain:.1f}dB,"
              f"aformat=sample_rates=48000:channel_layouts=stereo,adelay={int(at*1000)}:all=1[mu]"); labels.append("[mu]"); total = at + L
rt = C.get("room_tone_seconds", 0)
if rt:   # quiet pink noise under the story so gaps between lines are not dead air
    fc.append(f"anoisesrc=color=pink:sample_rate=48000:amplitude=0.004:duration={rt},lowpass=f=900,afade=t=in:d=1,afade=t=out:st={rt-2}:d=2,aformat=channel_layouts=stereo[rt]"); labels.append("[rt]")
# level=disabled matters: alimiter's default auto-level pushes the whole track up to 0 dB
fc.append(f"[0:a]apad=whole_dur={total:.3f}[n];[n]" + "".join(labels[1:]) + f"amix=inputs={len(labels)}:duration=first:normalize=0,volume=-1dB,alimiter=limit=0.89:level=disabled[out]")
subprocess.run(["ffmpeg", "-y", "-loglevel", "error"] + inputs + ["-filter_complex", ";".join(fc), "-map", "[out]", "-c:a", "aac", "-b:a", "192k", f"{O}/{C['out']}"], check=True)
print(f"mixed {C['out']}: {dur(O + '/' + C['out']):.2f}s, mean {mean(O + '/' + C['out']):.1f} dB")
